#!/usr/bin/env python3
"""Render live-build bootloader configuration, release metadata and build info."""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path


def _repo(root: Path):
    sys.path.insert(0, str(root / "installer"))
    from spiral_installer.config import load_repository

    return load_repository(root)


def render_grub(repo, platform: str) -> str:
    lines = [
        "# Generated by builder/render_config.py. Do not edit by hand.",
        "if [ -f /boot/grub/config.cfg ]; then",
        "    source /boot/grub/config.cfg",
        "fi",
        f"set default={_default_index(repo)}",
        f"set timeout={repo.build.boot_timeout_seconds}",
        "",
    ]
    for index, entry in enumerate(repo.build.boot_entries):
        if entry.memtest:
            continue
        label = entry.label.replace("'", "")
        append = " ".join(part for part in (entry.append.strip(),) if part)
        lines.extend(
            [
                f"menuentry '{label}' --id spiral-{entry.id} {{",
                f"    linux @KERNEL_LIVE@ @APPEND_LIVE@ {append}".rstrip(),
                "    initrd @INITRD_LIVE@",
                "}",
                "",
            ]
        )
    memtest = next((entry for entry in repo.build.boot_entries if entry.memtest), None)
    if memtest and platform == "bios":
        lines.extend(["submenu 'Advanced options' {", "    MEMTEST", "}", ""])
    return "\n".join(lines)


def _default_index(repo) -> int:
    entries = [entry for entry in repo.build.boot_entries if not entry.memtest]
    for index, entry in enumerate(entries):
        if entry.id == repo.build.default_boot_entry:
            return index
    raise SystemExit("the default boot entry cannot be a memtest entry")


def boot_append(repo) -> str:
    return (
        "boot=live components "
        f"username={repo.build.live_username} hostname={repo.build.live_hostname} "
        "console=tty0 console=ttyS0,115200 quiet splash systemd.show_status=1"
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True)
    parser.add_argument("--config-dir", required=True)
    parser.add_argument("--release", required=True)
    parser.add_argument("--version", required=True)
    parser.add_argument("--bootappend-file", required=True)
    args = parser.parse_args()

    root = Path(args.root).resolve()
    config_dir = Path(args.config_dir).resolve()
    release_path = Path(args.release).resolve()
    repo = _repo(root)
    release = json.loads(release_path.read_text(encoding="utf-8"))
    if not isinstance(release, dict) or not release.get("codename"):
        raise SystemExit("release metadata is missing a codename")

    for platform in ("bios", "uefi"):
        directory = config_dir / "bootloaders" / ("grub-pc" if platform == "bios" else "grub-efi")
        directory.mkdir(parents=True, exist_ok=True)
        (directory / "grub.cfg").write_text(render_grub(repo, platform), encoding="utf-8")

    Path(args.bootappend_file).write_text(boot_append(repo) + "\n", encoding="utf-8")

    includes = config_dir / "includes.chroot" / "usr" / "share" / "spiral"
    includes.mkdir(parents=True, exist_ok=True)
    (includes / "release.json").write_text(json.dumps(release, indent=2) + "\n", encoding="utf-8")

    build_info = {
        "name": repo.build.name,
        "spiral_version": args.version,
        "debian": {
            "suite": release.get("suite", repo.debian.suite),
            "codename": release["codename"],
            "version": release.get("version", "unknown"),
        },
        "architecture": repo.debian.architecture,
        "git_commit": os.environ.get("SPIRAL_GIT_COMMIT", ""),
        "git_dirty": os.environ.get("SPIRAL_GIT_DIRTY", "") == "true",
        "source_date_epoch": os.environ.get("SOURCE_DATE_EPOCH", ""),
        "built_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "offline_enabled": repo.build.offline_enabled,
        "live_username": repo.build.live_username,
        "live_hostname": repo.build.live_hostname,
        "live_build_version": os.environ.get("SPIRAL_LIVE_BUILD_VERSION", ""),
        "boot_entries": [entry.id for entry in repo.build.boot_entries],
    }
    (includes / "build-info.json").write_text(json.dumps(build_info, indent=2) + "\n", encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
